   * SECURITY UPDATE: Excessive Memory Allocation in Relative CRLDP Processing
diff --git a/debian/patches/revert-engine-legacy-key-detection.patch b/debian/patches/revert-engine-legacy-key-detection.patch
new file mode 100644
index 0000000..d09e361
--- /dev/null
+++ b/debian/patches/revert-engine-legacy-key-detection.patch
@@ -0,0 +1,65 @@
+Description: Revert "Improved detection of engine-provided private classic keys"
+ The reverted change forces a get1/set1 round-trip on the key returned by
+ ENGINE_load_private_key(), which clears the key's pmeth_engine. The OpenSSL
+ PKCS#11 engine then gets NULL back from RSA_get_ex_data() and segfaults on
+ its RSA_sign path (LP: #2158304). Upstream reverted it for 3.0.14 as having
+ caused more problems than it solved; noble's 3.0.13 is the only supported
+ Ubuntu series still carrying it. Removing it here fixes the segfault at the
+ source, so libp11 can drop its process-global ENGINE_set_default_string()
+ workaround, which regressed unrelated provider-path RSA (LP: #2163152).
+Origin: backport, https://github.com/openssl/openssl/commit/ad6cbe4b7f57a783a66a7ae883ea0d35ef5f82b6
+Bug: https://github.com/openssl/openssl/issues/22945
+Bug-Ubuntu: https://bugs.launchpad.net/ubuntu/+source/openssl/+bug/2158304
+Applied-Upstream: 3.0.14
+Last-Update: 2026-10-24
+--- a/crypto/engine/eng_pkey.c
++++ b/crypto/engine/eng_pkey.c
+@@ -79,48 +79,6 @@
+         ERR_raise(ERR_LIB_ENGINE, ENGINE_R_FAILED_LOADING_PRIVATE_KEY);
+         return NULL;
+     }
+-    /* We enforce check for legacy key */
+-    switch (EVP_PKEY_get_id(pkey)) {
+-    case EVP_PKEY_RSA:
+-        {
+-        RSA *rsa = EVP_PKEY_get1_RSA(pkey);
+-        EVP_PKEY_set1_RSA(pkey, rsa);
+-        RSA_free(rsa);
+-        }
+-        break;
+-#  ifndef OPENSSL_NO_EC
+-    case EVP_PKEY_SM2:
+-    case EVP_PKEY_EC:
+-        {
+-        EC_KEY *ec = EVP_PKEY_get1_EC_KEY(pkey);
+-        EVP_PKEY_set1_EC_KEY(pkey, ec);
+-        EC_KEY_free(ec);
+-        }
+-        break;
+-#  endif
+-#  ifndef OPENSSL_NO_DSA
+-    case EVP_PKEY_DSA:
+-        {
+-        DSA *dsa = EVP_PKEY_get1_DSA(pkey);
+-        EVP_PKEY_set1_DSA(pkey, dsa);
+-        DSA_free(dsa);
+-        }
+-        break;
+-#endif
+-#  ifndef OPENSSL_NO_DH
+-    case EVP_PKEY_DH:
+-        {
+-        DH *dh = EVP_PKEY_get1_DH(pkey);
+-        EVP_PKEY_set1_DH(pkey, dh);
+-        DH_free(dh);
+-        }
+-        break;
+-#endif
+-    default:
+-        /*Do nothing */
+-        break;
+-    }
+-
+     return pkey;
+ }
+ 
